                (aggregation) -> aggregation.pipeline(facet().field("price", autoBucket().groupBy("$price").buckets(4))
                        .field("year",
                                autoBucket().groupBy("$year").buckets(3).outputField("count", sum(1))
                                        .outputField("years", push("$year")))
